        raise ValueError('h must be positive')
    if not point:
        raise ValueError('need at least one coordinate')
    out = []
    for i in range(len(point)):
        up, down = list(point), list(point)
        up[i] += h
        down[i] -= h
        out.append((f(up) - f(down)) / (2 * h))
    return out


def check_gradient(f, grad, point, h=1e-5, tol=1e-6):
    if not tol >= 0:
        raise ValueError('tol must not be negative')
    numeric = gradient(f, point, h)
    analytic = list(grad(point))
    if len(analytic) != len(numeric):
        raise ValueError('grad returned the wrong number of components')
    worst = max(abs(a - n) / max(1.0, abs(a), abs(n)) for a, n in zip(analytic, numeric))
    return worst <= tol, worst

